styl:
u + .body .gmail-blend-screen { background: #000;
  mix-blend-mode: screen; }
u + .body .gmail-blend-diff { background: #000;
  mix-blend-mode: difference; }
.bgr-image { background: url("https://fsms.quadcode.com/storage/public/d6/1e/vbvvhhgea139ula0/rfm-324-head.png") center top no-repeat;
  background-size: cover;
  background-color: #000; }
.opacity-block { background: url("https://fsms.quadcode.com/storage/public/d6/1e/vbvvhhgea139ul90/rfm-324-backgroung.png") center top no-repeat;
  background-size: cover;
  padding: 24px;
  border-radius: 24px; }
.w280 { width: 100%;
  max-width: 280px; }
@media screen and (max-width: 600px) {
  .w280 { max-width: 100% !important; }
}
.brad-full { border-radius: 32px !important; }
.butt-link { font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px; }
.white-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 40px;
  line-height: 50px;
  color: #fff;
  word-break: break-word; }
@media screen and (max-width: 600px) {
  .white-title { font-size: 26px !important;
    line-height: 32px !important; }
}
.small-white-title { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 24px;
  line-height: 31px;
  color: #fff; }
.white-text { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;
  padding-right: 20px; }
@media screen and (max-width: 600px) {
  .white-text { padding-right: 0 !important; }
}
.ava { width: 50px !important;
  float: none; }
.pb16 { padding-bottom: 16px; }
.h-24 { font-size: 8px;
  line-height: 24px;
  height: 24px; }
.h-406 { font-size: 0;
  line-height: 336px;
  height: 336px; }
@media screen and (max-width: 500px) {
  .h-406 { font-size: 160px !important;
    line-height: 300px !important;
    height: 300px !important; }
}
.w100 { width: 100%; }
.w-a { width: auto !important;
  vertical-align: middle; }
table[class=body] table.column td,
table[class=body] table.columns td.m-w { min-width: 74px !important;
  width: 74px !important; }
